insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (93, 6, 91, 99, 'سورة الأنعام ٩١ – ٩٩', '«وما قدروا الله حق قدره»، وسكرات الظالمين، و«إن الله فالق الحب والنوى»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 93) = $j$[{"lbl": "الآيتان ٩١ – ٩٢", "q": "وَمَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓ إِذۡ قَالُواْ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ بَشَرٖ مِّن شَيۡءٖۗ قُلۡ مَنۡ أَنزَلَ ٱلۡكِتَٰبَ ٱلَّذِي جَآءَ بِهِۦ مُوسَىٰ نُورٗا وَهُدٗى لِّلنَّاسِۖ تَجۡعَلُونَهُۥ قَرَاطِيسَ تُبۡدُونَهَا وَتُخۡفُونَ كَثِيرٗاۖ وَعُلِّمۡتُم مَّا لَمۡ تَعۡلَمُوٓاْ أَنتُمۡ وَلَآ ءَابَآؤُكُمۡۖ قُلِ ٱللَّهُۖ ثُمَّ ذَرۡهُمۡ فِي خَوۡضِهِمۡ يَلۡعَبُونَ ﴿٩١﴾ وَهَٰذَا كِتَٰبٌ أَنزَلۡنَٰهُ مُبَارَكٞ مُّصَدِّقُ ٱلَّذِي بَيۡنَ يَدَيۡهِ وَلِتُنذِرَ أُمَّ ٱلۡقُرَىٰ وَمَنۡ حَوۡلَهَاۚ وَٱلَّذِينَ يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ يُؤۡمِنُونَ بِهِۦۖ وَهُمۡ عَلَىٰ صَلَاتِهِمۡ يُحَافِظُونَ ﴿٩٢﴾", "w": [["وما قدروا الله حق قدره", "ما عظّموه التعظيم اللائق به، ولا عرفوه حق معرفته."], ["على بشر", "أي إنسان من بني آدم."], ["الكتاب الذي جاء به موسى", "التوراة."], ["قراطيس", "جمع قرطاس، وهو ما يُكتب عليه من ورق وغيره."], ["تبدونها", "تُظهرونها."], ["قل الله", "هذا جواب: من أنزل الكتاب؟"], ["ذرهم", "اتركهم."], ["في خوضهم", "فيما يخوضون فيه من الباطل."], ["مبارك", "مبارك فيه، فخيره لا ينقطع وبركته لا تزول."], ["أم القرى", "مكة المكرمة."], ["يحافظون", "يؤدّونها بطهارة في أوقاتها المحددة لها في جماعة المؤمنين."]], "m": "أنكر الله على المشركين إنكارهم للوحي إذ قالوا: ما أنزل الله على بشر من شيء، ولقّن رسوله الحجة: قل من أنزل الكتاب الذي جاء به موسى نوراً يُستضاء به في الطريق إلى الله وهدى، وهو التوراة التي جعلها اليهود قراطيس يُبدون بعضها ويُخفون كثيراً حسب أهوائهم وأطماعهم، وعُلّمتم بهذا القرآن ما لم تعلموا أنتم ولا آباؤكم من توحيد الله وأسمائه وصفاته والدار الآخرة؟ قل الله، ثم ذرهم في خوضهم يلعبون، لا يحصلون منه على فائدة كاللاعبين من الأطفال. وكيف يقال ما أنزل الله على بشر من شيء وهذا القرآن بين أيديهم، أنزلناه مباركاً لا ينتهي خيره، مصدّقاً لما سبقه من الكتب، ولتنذر أهل مكة ومن حولها من المدن والقرى القريبة والبعيدة عاقبة الكفر والضلال، والذين يؤمنون بالآخرة يؤمنون به، وهم على صلاتهم يحافظون.", "h": ["كل من كذّب الله تعالى أو أشرك به أو وصفه بوصف لا يليق بجلاله فإنه لم يقدر الله حق قدره.", "بيان تلاعب اليهود بكتاب الله في إبداء بعض أخباره وأحكامه وإخفاء بعض آخر، وهو تصرّف ناتج من الهوى واتباع الشهوات وإيثار الدنيا على الآخرة.", "بيان فضل الله على العرب بإنزال هذا الكتاب العظيم عليهم بلغتهم لهدايتهم.", "تعليم الرسول ﷺ كيفية الحجاج والرد على المجادلين والكاذبين.", "بيان علة نزول الكتاب، وهي الإيمان به وإنذار المكذبين والمشركين.", "الإيمان بالآخرة سبب لكل خير، والكفر بها سبب لكل باطل وشر."], "k": "«تبدونها وتخفون كثيراً»… هل آخذ من الدين ما يوافق هواي، وأُخفي عن نفسي ما يخالفه؟"}, {"lbl": "الآيتان ٩٣ – ٩٤", "q": "وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ قَالَ أُوحِيَ إِلَيَّ وَلَمۡ يُوحَ إِلَيۡهِ شَيۡءٞ وَمَن قَالَ سَأُنزِلُ مِثۡلَ مَآ أَنزَلَ ٱللَّهُۗ وَلَوۡ تَرَىٰٓ إِذِ ٱلظَّـٰلِمُونَ فِي غَمَرَٰتِ ٱلۡمَوۡتِ وَٱلۡمَلَـٰٓئِكَةُ بَاسِطُوٓاْ أَيۡدِيهِمۡ أَخۡرِجُوٓاْ أَنفُسَكُمُۖ ٱلۡيَوۡمَ تُجۡزَوۡنَ عَذَابَ ٱلۡهُونِ بِمَا كُنتُمۡ تَقُولُونَ عَلَى ٱللَّهِ غَيۡرَ ٱلۡحَقِّ وَكُنتُمۡ عَنۡ ءَايَٰتِهِۦ تَسۡتَكۡبِرُونَ ﴿٩٣﴾ وَلَقَدۡ جِئۡتُمُونَا فُرَٰدَىٰ كَمَا خَلَقۡنَٰكُمۡ أَوَّلَ مَرَّةٖ وَتَرَكۡتُم مَّا خَوَّلۡنَٰكُمۡ وَرَآءَ ظُهُورِكُمۡۖ وَمَا نَرَىٰ مَعَكُمۡ شُفَعَآءَكُمُ ٱلَّذِينَ زَعَمۡتُمۡ أَنَّهُمۡ فِيكُمۡ شُرَكَـٰٓؤُاْۚ لَقَد تَّقَطَّعَ بَيۡنَكُمۡ وَضَلَّ عَنكُم مَّا كُنتُمۡ تَزۡعُمُونَ ﴿٩٤﴾", "w": [["افترى على الله كذباً", "اختلق على الله كذباً، قال عليه ما لم يقل، أو نسب له ما هو منه براء."], ["أوحي إليّ", "الوحي: الإعلام السريع الخفي بواسطة الملك وبغيره."], ["غمرات الموت", "شدائده عند نزع الروح."], ["باسطو أيديهم", "للضرب وإخراج الروح."], ["عذاب الهون", "عذاب الذل والمهانة."], ["فرادى", "واحداً واحداً، ليس مع أحدكم مال ولا رجال."], ["ما خوّلناكم", "ما أعطيناكم من مال ومتاع."], ["وراء ظهوركم", "أي في دار الدنيا."], ["وضلّ عنكم", "غاب."], ["تزعمون", "تدّعون كاذبين."]], "m": "ومن أظلم ممن افترى على الله كذباً فادّعى أن الله نبّأه، كما ادّعى ابن أبي سرح بمكة، ومسيلمة في بني حنيفة بنجد، والعنسي باليمن؟ لا أحد أظلم منه، ولا ممن قال أوحي إليّ ولم يوحَ إليه شيء، ومن قال سأنزل مثل ما أنزل الله. ولو ترى يا رسولنا إذ الظالمون في شدائد سكرات الموت، والملائكة، ملك الموت وأعوانه، باسطو أيديهم بالضرب وإخراج الروح، يقولون لهم تعجيزاً وتعذيباً: أخرجوا أنفسكم، اليوم تُجزون عذاب الهون بما كنتم تقولون على الله غير الحق، وكنتم عن آياته تستكبرون، واستكبار من أصله نطفة قذرة ونهايته جيفة قذرة استكبار باطل لا يصح بحال. ولقد جئتمونا فرادى كما خلقناكم أول مرة حفاة عراة، وتركتم ما أعطيناكم من مال وولد في دار الدنيا، وما نرى معكم شفعاءكم الذين زعمتم أنهم فيكم شركاء، لقد انحلّ حبل الولاء بينكم، وغاب عنكم ما كنتم تكذبون به في الدنيا.", "h": ["قبح الكذب على الله تعالى في أي شكل، وأن صاحبه لا أظلم منه قط.", "تقرير عذاب القبر، وسكرات الموت وشدتها، وفي الحديث: «إن للموت سكرات».", "قبح الاستكبار وعظم جرمه.", "تقرير عقيدة البعث الآخر، والجزاء على الكسب في الدنيا.", "انعدام الشفعاء يوم القيامة، إلا ما قضت به السنة الصحيحة من شفاعة النبي ﷺ والعلماء والشهداء، بشروط هي: أن يأذن الله للشافع أن يشفع، وأن يرضى عن المشفوع له."], "k": "«ولقد جئتمونا فرادى»… ماذا سأحمل معي حين أترك كل ما خُوّلته وراء ظهري؟"}, {"lbl": "الآيات ٩٥ – ٩٩", "q": "۞إِنَّ ٱللَّهَ فَالِقُ ٱلۡحَبِّ وَٱلنَّوَىٰۖ يُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَمُخۡرِجُ ٱلۡمَيِّتِ مِنَ ٱلۡحَيِّۚ ذَٰلِكُمُ ٱللَّهُۖ فَأَنَّىٰ تُؤۡفَكُونَ ﴿٩٥﴾ فَالِقُ ٱلۡإِصۡبَاحِ وَجَعَلَ ٱلَّيۡلَ سَكَنٗا وَٱلشَّمۡسَ وَٱلۡقَمَرَ حُسۡبَانٗاۚ ذَٰلِكَ تَقۡدِيرُ ٱلۡعَزِيزِ ٱلۡعَلِيمِ ﴿٩٦﴾ وَهُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلنُّجُومَ لِتَهۡتَدُواْ بِهَا فِي ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِۗ قَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ ﴿٩٧﴾ وَهُوَ ٱلَّذِيٓ أَنشَأَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ فَمُسۡتَقَرّٞ وَمُسۡتَوۡدَعٞۗ قَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمٖ يَفۡقَهُونَ ﴿٩٨﴾ وَهُوَ ٱلَّذِيٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦ نَبَاتَ كُلِّ شَيۡءٖ فَأَخۡرَجۡنَا مِنۡهُ خَضِرٗا نُّخۡرِجُ مِنۡهُ حَبّٗا مُّتَرَاكِبٗا وَمِنَ ٱلنَّخۡلِ مِن طَلۡعِهَا قِنۡوَانٞ دَانِيَةٞ وَجَنَّـٰتٖ مِّنۡ أَعۡنَابٖ وَٱلزَّيۡتُونَ وَٱلرُّمَّانَ مُشۡتَبِهٗا وَغَيۡرَ مُتَشَٰبِهٍۗ ٱنظُرُوٓاْ إِلَىٰ ثَمَرِهِۦٓ إِذَآ أَثۡمَرَ وَيَنۡعِهِۦٓۚ إِنَّ فِي ذَٰلِكُمۡ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ ﴿٩٩﴾", "w": [["فالق الحب والنوى", "شاقّ الحب كحب البُرّ ليخرج منه الزرع، والنوى واحده نواة، وشقّها ليخرج منها الفسيلة (النخلة الصغيرة)."], ["يخرج الحي من الميت", "كالدجاجة من البيضة."], ["ومخرج الميت من الحي", "كالبيضة من الدجاجة."], ["فأنى تؤفكون", "كيف تُصرفون عن توحيد الله الذي هذه قدرته إلى عبادة الجمادات؟"], ["فالق الإصباح", "الإصباح بمعنى الصبح، وفلقه: شقّه ليتفجّر منه النور والضياء."], ["سكناً", "يسكن فيه الناس ويخلدون للراحة."], ["حسباناً", "حساباً به تُعرف الأوقات: الأيام والليالي والشهور والسنون."], ["تقدير العزيز العليم", "إيجاد وتنظيم العزيز الغالب على أمره، العليم بأحوال عباده وأفعالهم."], ["لتهتدوا بها", "ليهتدي بها المسافرون في معرفة طرقهم في البر والبحر."], ["من نفس واحدة", "هي آدم ﵇ أبو البشر."], ["فمستقر", "أي في الأرحام."], ["ومستودع", "أي في أصلاب الرجال."], ["يفقهون", "أسرار الأشياء وعلل الأفعال، فيهتدون لما هو حق وخير."], ["خضراً", "أول ما يخرج من الزرع، ويقال له القصيل الأخضر."], ["متراكباً", "بعضه فوق بعض، وهو ظاهر في السنبلة."], ["طلع النخل", "زهرها."], ["قنوان", "واحده قنو، وهو العذق."], ["مشتبهاً وغير متشابه", "مشتبهاً في اللون، وغير متشابه في الطعم."], ["وينعه", "نضجه واستوائه."]], "m": "ما زال السياق في بيان الدليل على وجوب توحيد الله، فوصف نفسه بأفعاله العظيمة التي تُثبت ربوبيته وتُبطل ألوهية غيره: إن الله فالق الحب فيُخرج منه الزرع، والنوى فيُخرج منه الشجر والنخل، يُخرج الزرع الحي من الحب الميت، ومُخرج الحب الميت من الزرع الحي، ذلكم الله المستحق للعبادة وحده، فكيف يا للعجب تُصرفون عنه إلى غيره؟ هو فالق ظلام الليل عن ضياء النهار، وجعل الليل سكناً تستريح فيه الأحياء من تعب النهار، والشمس والقمر يدوران بحساب، يعرف به الناس الأوقات وما يتوقف عليها من عبادات وآجال وحقوق، ذلك تقدير العزيز العليم، فعل ذلك لأجلهم، فكيف لا يستحق عبادتهم؟ وهو الذي جعل لكم النجوم لتهتدوا بها في ظلمات البر والبحر، قد فصّلنا الآيات لقوم يعلمون، يميّزون بنور العلم بين الحق والباطل. وهو الذي أنشأكم من نفس واحدة، آدم ﵇، فبعضكم مستقر في الأرحام وبعضكم مستودع في الأصلاب، قد فصّلنا الآيات لقوم يفقهون. وهو الذي أنزل من السماء ماء المطر فأخرجنا به نبات كل شيء، فأخرجنا منه زرعاً أخضر، نُخرج منه حباً متراكباً في سنابله، ومن طلع النخل عذوق دانية قريبة التناول، وجنات من أعناب، والزيتون والرمان مشتبهاً في اللون وغير متشابه في الطعم، انظروا إلى ثمره إذا أثمر وإلى نضجه، إن في ذلكم لآيات لقوم يؤمنون، لأنهم أحياء يفكرون ويفهمون، أما أهل الكفر فقلوبهم ميتة بما ران عليها من الشرك والمعاصي.", "h": ["الله خالق كل شيء فهو رب كل شيء، ولذا وجب أن يُؤلّه وحده دون ما سواه.", "تقرير قدرة الله على كل شيء، وعلمه بكل شيء، وحكمته في كل شيء.", "فائدة خلق النجوم، وهي الاهتداء بها في السير ليلاً في البر والبحر.", "يتم إدراك ظواهر الأمور وبواطنها بالعقل.", "يتم إدراك أسرار الأشياء بالفقه.", "الإيمان بمثابة الحياة، والكفر بمثابة الموت في إدراك الأمور."], "k": "«انظروا إلى ثمره إذا أثمر وينعه»… متى آخر مرة تأمّلت حبة أو ثمرة فعرفت فيها ربي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 93;
insert into public.tdb_cards(topic, i, body) select 93, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ٩١ – ٩٢", "q": "وَمَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓ إِذۡ قَالُواْ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ بَشَرٖ مِّن شَيۡءٖۗ قُلۡ مَنۡ أَنزَلَ ٱلۡكِتَٰبَ ٱلَّذِي جَآءَ بِهِۦ مُوسَىٰ نُورٗا وَهُدٗى لِّلنَّاسِۖ تَجۡعَلُونَهُۥ قَرَاطِيسَ تُبۡدُونَهَا وَتُخۡفُونَ كَثِيرٗاۖ وَعُلِّمۡتُم مَّا لَمۡ تَعۡلَمُوٓاْ أَنتُمۡ وَلَآ ءَابَآؤُكُمۡۖ قُلِ ٱللَّهُۖ ثُمَّ ذَرۡهُمۡ فِي خَوۡضِهِمۡ يَلۡعَبُونَ ﴿٩١﴾ وَهَٰذَا كِتَٰبٌ أَنزَلۡنَٰهُ مُبَارَكٞ مُّصَدِّقُ ٱلَّذِي بَيۡنَ يَدَيۡهِ وَلِتُنذِرَ أُمَّ ٱلۡقُرَىٰ وَمَنۡ حَوۡلَهَاۚ وَٱلَّذِينَ يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ يُؤۡمِنُونَ بِهِۦۖ وَهُمۡ عَلَىٰ صَلَاتِهِمۡ يُحَافِظُونَ ﴿٩٢﴾", "w": [["وما قدروا الله حق قدره", "ما عظّموه التعظيم اللائق به، ولا عرفوه حق معرفته."], ["على بشر", "أي إنسان من بني آدم."], ["الكتاب الذي جاء به موسى", "التوراة."], ["قراطيس", "جمع قرطاس، وهو ما يُكتب عليه من ورق وغيره."], ["تبدونها", "تُظهرونها."], ["قل الله", "هذا جواب: من أنزل الكتاب؟"], ["ذرهم", "اتركهم."], ["في خوضهم", "فيما يخوضون فيه من الباطل."], ["مبارك", "مبارك فيه، فخيره لا ينقطع وبركته لا تزول."], ["أم القرى", "مكة المكرمة."], ["يحافظون", "يؤدّونها بطهارة في أوقاتها المحددة لها في جماعة المؤمنين."]], "m": "أنكر الله على المشركين إنكارهم للوحي إذ قالوا: ما أنزل الله على بشر من شيء، ولقّن رسوله الحجة: قل من أنزل الكتاب الذي جاء به موسى نوراً يُستضاء به في الطريق إلى الله وهدى، وهو التوراة التي جعلها اليهود قراطيس يُبدون بعضها ويُخفون كثيراً حسب أهوائهم وأطماعهم، وعُلّمتم بهذا القرآن ما لم تعلموا أنتم ولا آباؤكم من توحيد الله وأسمائه وصفاته والدار الآخرة؟ قل الله، ثم ذرهم في خوضهم يلعبون، لا يحصلون منه على فائدة كاللاعبين من الأطفال. وكيف يقال ما أنزل الله على بشر من شيء وهذا القرآن بين أيديهم، أنزلناه مباركاً لا ينتهي خيره، مصدّقاً لما سبقه من الكتب، ولتنذر أهل مكة ومن حولها من المدن والقرى القريبة والبعيدة عاقبة الكفر والضلال، والذين يؤمنون بالآخرة يؤمنون به، وهم على صلاتهم يحافظون.", "h": ["كل من كذّب الله تعالى أو أشرك به أو وصفه بوصف لا يليق بجلاله فإنه لم يقدر الله حق قدره.", "بيان تلاعب اليهود بكتاب الله في إبداء بعض أخباره وأحكامه وإخفاء بعض آخر، وهو تصرّف ناتج من الهوى واتباع الشهوات وإيثار الدنيا على الآخرة.", "بيان فضل الله على العرب بإنزال هذا الكتاب العظيم عليهم بلغتهم لهدايتهم.", "تعليم الرسول ﷺ كيفية الحجاج والرد على المجادلين والكاذبين.", "بيان علة نزول الكتاب، وهي الإيمان به وإنذار المكذبين والمشركين.", "الإيمان بالآخرة سبب لكل خير، والكفر بها سبب لكل باطل وشر."], "k": "«تبدونها وتخفون كثيراً»… هل آخذ من الدين ما يوافق هواي، وأُخفي عن نفسي ما يخالفه؟"}, {"lbl": "الآيتان ٩٣ – ٩٤", "q": "وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ قَالَ أُوحِيَ إِلَيَّ وَلَمۡ يُوحَ إِلَيۡهِ شَيۡءٞ وَمَن قَالَ سَأُنزِلُ مِثۡلَ مَآ أَنزَلَ ٱللَّهُۗ وَلَوۡ تَرَىٰٓ إِذِ ٱلظَّـٰلِمُونَ فِي غَمَرَٰتِ ٱلۡمَوۡتِ وَٱلۡمَلَـٰٓئِكَةُ بَاسِطُوٓاْ أَيۡدِيهِمۡ أَخۡرِجُوٓاْ أَنفُسَكُمُۖ ٱلۡيَوۡمَ تُجۡزَوۡنَ عَذَابَ ٱلۡهُونِ بِمَا كُنتُمۡ تَقُولُونَ عَلَى ٱللَّهِ غَيۡرَ ٱلۡحَقِّ وَكُنتُمۡ عَنۡ ءَايَٰتِهِۦ تَسۡتَكۡبِرُونَ ﴿٩٣﴾ وَلَقَدۡ جِئۡتُمُونَا فُرَٰدَىٰ كَمَا خَلَقۡنَٰكُمۡ أَوَّلَ مَرَّةٖ وَتَرَكۡتُم مَّا خَوَّلۡنَٰكُمۡ وَرَآءَ ظُهُورِكُمۡۖ وَمَا نَرَىٰ مَعَكُمۡ شُفَعَآءَكُمُ ٱلَّذِينَ زَعَمۡتُمۡ أَنَّهُمۡ فِيكُمۡ شُرَكَـٰٓؤُاْۚ لَقَد تَّقَطَّعَ بَيۡنَكُمۡ وَضَلَّ عَنكُم مَّا كُنتُمۡ تَزۡعُمُونَ ﴿٩٤﴾", "w": [["افترى على الله كذباً", "اختلق على الله كذباً، قال عليه ما لم يقل، أو نسب له ما هو منه براء."], ["أوحي إليّ", "الوحي: الإعلام السريع الخفي بواسطة الملك وبغيره."], ["غمرات الموت", "شدائده عند نزع الروح."], ["باسطو أيديهم", "للضرب وإخراج الروح."], ["عذاب الهون", "عذاب الذل والمهانة."], ["فرادى", "واحداً واحداً، ليس مع أحدكم مال ولا رجال."], ["ما خوّلناكم", "ما أعطيناكم من مال ومتاع."], ["وراء ظهوركم", "أي في دار الدنيا."], ["وضلّ عنكم", "غاب."], ["تزعمون", "تدّعون كاذبين."]], "m": "ومن أظلم ممن افترى على الله كذباً فادّعى أن الله نبّأه، كما ادّعى ابن أبي سرح بمكة، ومسيلمة في بني حنيفة بنجد، والعنسي باليمن؟ لا أحد أظلم منه، ولا ممن قال أوحي إليّ ولم يوحَ إليه شيء، ومن قال سأنزل مثل ما أنزل الله. ولو ترى يا رسولنا إذ الظالمون في شدائد سكرات الموت، والملائكة، ملك الموت وأعوانه، باسطو أيديهم بالضرب وإخراج الروح، يقولون لهم تعجيزاً وتعذيباً: أخرجوا أنفسكم، اليوم تُجزون عذاب الهون بما كنتم تقولون على الله غير الحق، وكنتم عن آياته تستكبرون، واستكبار من أصله نطفة قذرة ونهايته جيفة قذرة استكبار باطل لا يصح بحال. ولقد جئتمونا فرادى كما خلقناكم أول مرة حفاة عراة، وتركتم ما أعطيناكم من مال وولد في دار الدنيا، وما نرى معكم شفعاءكم الذين زعمتم أنهم فيكم شركاء، لقد انحلّ حبل الولاء بينكم، وغاب عنكم ما كنتم تكذبون به في الدنيا.", "h": ["قبح الكذب على الله تعالى في أي شكل، وأن صاحبه لا أظلم منه قط.", "تقرير عذاب القبر، وسكرات الموت وشدتها، وفي الحديث: «إن للموت سكرات».", "قبح الاستكبار وعظم جرمه.", "تقرير عقيدة البعث الآخر، والجزاء على الكسب في الدنيا.", "انعدام الشفعاء يوم القيامة، إلا ما قضت به السنة الصحيحة من شفاعة النبي ﷺ والعلماء والشهداء، بشروط هي: أن يأذن الله للشافع أن يشفع، وأن يرضى عن المشفوع له."], "k": "«ولقد جئتمونا فرادى»… ماذا سأحمل معي حين أترك كل ما خُوّلته وراء ظهري؟"}, {"lbl": "الآيات ٩٥ – ٩٩", "q": "۞إِنَّ ٱللَّهَ فَالِقُ ٱلۡحَبِّ وَٱلنَّوَىٰۖ يُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَمُخۡرِجُ ٱلۡمَيِّتِ مِنَ ٱلۡحَيِّۚ ذَٰلِكُمُ ٱللَّهُۖ فَأَنَّىٰ تُؤۡفَكُونَ ﴿٩٥﴾ فَالِقُ ٱلۡإِصۡبَاحِ وَجَعَلَ ٱلَّيۡلَ سَكَنٗا وَٱلشَّمۡسَ وَٱلۡقَمَرَ حُسۡبَانٗاۚ ذَٰلِكَ تَقۡدِيرُ ٱلۡعَزِيزِ ٱلۡعَلِيمِ ﴿٩٦﴾ وَهُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلنُّجُومَ لِتَهۡتَدُواْ بِهَا فِي ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِۗ قَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ ﴿٩٧﴾ وَهُوَ ٱلَّذِيٓ أَنشَأَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ فَمُسۡتَقَرّٞ وَمُسۡتَوۡدَعٞۗ قَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمٖ يَفۡقَهُونَ ﴿٩٨﴾ وَهُوَ ٱلَّذِيٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦ نَبَاتَ كُلِّ شَيۡءٖ فَأَخۡرَجۡنَا مِنۡهُ خَضِرٗا نُّخۡرِجُ مِنۡهُ حَبّٗا مُّتَرَاكِبٗا وَمِنَ ٱلنَّخۡلِ مِن طَلۡعِهَا قِنۡوَانٞ دَانِيَةٞ وَجَنَّـٰتٖ مِّنۡ أَعۡنَابٖ وَٱلزَّيۡتُونَ وَٱلرُّمَّانَ مُشۡتَبِهٗا وَغَيۡرَ مُتَشَٰبِهٍۗ ٱنظُرُوٓاْ إِلَىٰ ثَمَرِهِۦٓ إِذَآ أَثۡمَرَ وَيَنۡعِهِۦٓۚ إِنَّ فِي ذَٰلِكُمۡ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ ﴿٩٩﴾", "w": [["فالق الحب والنوى", "شاقّ الحب كحب البُرّ ليخرج منه الزرع، والنوى واحده نواة، وشقّها ليخرج منها الفسيلة (النخلة الصغيرة)."], ["يخرج الحي من الميت", "كالدجاجة من البيضة."], ["ومخرج الميت من الحي", "كالبيضة من الدجاجة."], ["فأنى تؤفكون", "كيف تُصرفون عن توحيد الله الذي هذه قدرته إلى عبادة الجمادات؟"], ["فالق الإصباح", "الإصباح بمعنى الصبح، وفلقه: شقّه ليتفجّر منه النور والضياء."], ["سكناً", "يسكن فيه الناس ويخلدون للراحة."], ["حسباناً", "حساباً به تُعرف الأوقات: الأيام والليالي والشهور والسنون."], ["تقدير العزيز العليم", "إيجاد وتنظيم العزيز الغالب على أمره، العليم بأحوال عباده وأفعالهم."], ["لتهتدوا بها", "ليهتدي بها المسافرون في معرفة طرقهم في البر والبحر."], ["من نفس واحدة", "هي آدم ﵇ أبو البشر."], ["فمستقر", "أي في الأرحام."], ["ومستودع", "أي في أصلاب الرجال."], ["يفقهون", "أسرار الأشياء وعلل الأفعال، فيهتدون لما هو حق وخير."], ["خضراً", "أول ما يخرج من الزرع، ويقال له القصيل الأخضر."], ["متراكباً", "بعضه فوق بعض، وهو ظاهر في السنبلة."], ["طلع النخل", "زهرها."], ["قنوان", "واحده قنو، وهو العذق."], ["مشتبهاً وغير متشابه", "مشتبهاً في اللون، وغير متشابه في الطعم."], ["وينعه", "نضجه واستوائه."]], "m": "ما زال السياق في بيان الدليل على وجوب توحيد الله، فوصف نفسه بأفعاله العظيمة التي تُثبت ربوبيته وتُبطل ألوهية غيره: إن الله فالق الحب فيُخرج منه الزرع، والنوى فيُخرج منه الشجر والنخل، يُخرج الزرع الحي من الحب الميت، ومُخرج الحب الميت من الزرع الحي، ذلكم الله المستحق للعبادة وحده، فكيف يا للعجب تُصرفون عنه إلى غيره؟ هو فالق ظلام الليل عن ضياء النهار، وجعل الليل سكناً تستريح فيه الأحياء من تعب النهار، والشمس والقمر يدوران بحساب، يعرف به الناس الأوقات وما يتوقف عليها من عبادات وآجال وحقوق، ذلك تقدير العزيز العليم، فعل ذلك لأجلهم، فكيف لا يستحق عبادتهم؟ وهو الذي جعل لكم النجوم لتهتدوا بها في ظلمات البر والبحر، قد فصّلنا الآيات لقوم يعلمون، يميّزون بنور العلم بين الحق والباطل. وهو الذي أنشأكم من نفس واحدة، آدم ﵇، فبعضكم مستقر في الأرحام وبعضكم مستودع في الأصلاب، قد فصّلنا الآيات لقوم يفقهون. وهو الذي أنزل من السماء ماء المطر فأخرجنا به نبات كل شيء، فأخرجنا منه زرعاً أخضر، نُخرج منه حباً متراكباً في سنابله، ومن طلع النخل عذوق دانية قريبة التناول، وجنات من أعناب، والزيتون والرمان مشتبهاً في اللون وغير متشابه في الطعم، انظروا إلى ثمره إذا أثمر وإلى نضجه، إن في ذلكم لآيات لقوم يؤمنون، لأنهم أحياء يفكرون ويفهمون، أما أهل الكفر فقلوبهم ميتة بما ران عليها من الشرك والمعاصي.", "h": ["الله خالق كل شيء فهو رب كل شيء، ولذا وجب أن يُؤلّه وحده دون ما سواه.", "تقرير قدرة الله على كل شيء، وعلمه بكل شيء، وحكمته في كل شيء.", "فائدة خلق النجوم، وهي الاهتداء بها في السير ليلاً في البر والبحر.", "يتم إدراك ظواهر الأمور وبواطنها بالعقل.", "يتم إدراك أسرار الأشياء بالفقه.", "الإيمان بمثابة الحياة، والكفر بمثابة الموت في إدراك الأمور."], "k": "«انظروا إلى ثمره إذا أثمر وينعه»… متى آخر مرة تأمّلت حبة أو ثمرة فعرفت فيها ربي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (94, 6, 100, 110, 'سورة الأنعام ١٠٠ – ١١٠', '«بديع السماوات والأرض»، «قد جاءكم بصائر»، و«ولا تسبّوا الذين يدعون من دون الله»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 94) = $j$[{"lbl": "الآيات ١٠٠ – ١٠٣", "q": "وَجَعَلُواْ لِلَّهِ شُرَكَآءَ ٱلۡجِنَّ وَخَلَقَهُمۡۖ وَخَرَقُواْ لَهُۥ بَنِينَ وَبَنَٰتِۭ بِغَيۡرِ عِلۡمٖۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَصِفُونَ ﴿١٠٠﴾ بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ أَنَّىٰ يَكُونُ لَهُۥ وَلَدٞ وَلَمۡ تَكُن لَّهُۥ صَٰحِبَةٞۖ وَخَلَقَ كُلَّ شَيۡءٖۖ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٞ ﴿١٠١﴾ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡۖ لَآ إِلَٰهَ إِلَّا هُوَۖ خَٰلِقُ كُلِّ شَيۡءٖ فَٱعۡبُدُوهُۚ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ وَكِيلٞ ﴿١٠٢﴾ لَّا تُدۡرِكُهُ ٱلۡأَبۡصَٰرُ وَهُوَ يُدۡرِكُ ٱلۡأَبۡصَٰرَۖ وَهُوَ ٱللَّطِيفُ ٱلۡخَبِيرُ ﴿١٠٣﴾", "w": [["شركاء", "جمع شريك في عبادته تعالى."], ["الجن", "عالم كعالم الإنس، إلا أنهم أجسام خفية لا تُرى لنا إلا إذا تشكّلت بما يُرى."], ["وخرقوا", "اختلقوا وافتاتوا."], ["يصفون", "من صفات العجز، بنسبة الولد والشريك إليه."], ["بديع السماوات والأرض", "مبدع خلقهما، حيث أوجدهما على غير مثال سابق."], ["أنى يكون له ولد", "كيف يكون له ولد كما يقول المبطلون؟"], ["ولم تكن له صاحبة", "أي زوجة."], ["لا تدركه الأبصار", "لا تراه في الدنيا، ولا تحيط به في الآخرة."], ["وهو يدرك الأبصار", "محيط علمه بها."], ["وهو اللطيف", "الذي ينفذ علمه إلى بواطن الأمور وخفايا الأسرار فلا يحجبه شيء."]], "m": "مع ما سبق من البراهين الباهرة على التوحيد، جعل الجاهلون لله شركاء الجن، فأطاعوهم فيما زيّنوا لهم من عبادة الأصنام، والحال أنه خلقهم، فالكل مخلوق له: العابد والمعبود. وزادوا في ضلالهم فاختلقوا له بنين وبنات بغير علم، لا دليل عقلي ولا نقلي، كما قال مشركو العرب: الملائكة بنات الله، واليهود: عزير ابن الله، والنصارى: المسيح ابن الله، سبحانه وتعالى عما يصفون. ثم أقام الدليل على بطلان هذه الفرية: بديع السماوات والأرض، خالقهما على غير مثال سابق، كيف يكون له ولد ولم تكن له زوجة؟ والتوالد إنما يكون بين ذكر وأنثى لحاجة حفظ النوع وعمارة الأرض، وهو خالق كل شيء ورب كل شيء، وهو بكل شيء عليم، فلو كان له ولد لعلمه. ذلكم الله ربكم لا إله إلا هو خالق كل شيء فاعبدوه، وهو على كل شيء وكيل، كفيل برزقكم وحفظكم ومجازاتكم. وهو مباين خلقه في ذاته وصفاته، لا تدركه الأبصار وهو يدركها، وهو اللطيف الذي ينفذ علمه وقدرته في كل ذرات الكون، الخبير بكل خلقه.", "h": ["من الإنس من عبد الجن، بطاعتهم وقبول ما يأمرونهم به ويزيّنونه لهم.", "تنزّه الرب تعالى عن الشريك والصاحبة والولد.", "مباينة الرب تبارك وتعالى لخلقه.", "استحالة رؤية الرب في الدنيا، وجوازها في الآخرة لأوليائه في دار كرامته."], "k": "«وهو اللطيف الخبير»… ربي يعلم خفايا نفسي التي لا يراها أحد؛ فهل أُصلحها كما أُصلح ظاهري؟"}, {"lbl": "الآيات ١٠٤ – ١٠٧", "q": "قَدۡ جَآءَكُم بَصَآئِرُ مِن رَّبِّكُمۡۖ فَمَنۡ أَبۡصَرَ فَلِنَفۡسِهِۦۖ وَمَنۡ عَمِيَ فَعَلَيۡهَاۚ وَمَآ أَنَا۠ عَلَيۡكُم بِحَفِيظٖ ﴿١٠٤﴾ وَكَذَٰلِكَ نُصَرِّفُ ٱلۡأٓيَٰتِ وَلِيَقُولُواْ دَرَسۡتَ وَلِنُبَيِّنَهُۥ لِقَوۡمٖ يَعۡلَمُونَ ﴿١٠٥﴾ ٱتَّبِعۡ مَآ أُوحِيَ إِلَيۡكَ مِن رَّبِّكَۖ لَآ إِلَٰهَ إِلَّا هُوَۖ وَأَعۡرِضۡ عَنِ ٱلۡمُشۡرِكِينَ ﴿١٠٦﴾ وَلَوۡ شَآءَ ٱللَّهُ مَآ أَشۡرَكُواْۗ وَمَا جَعَلۡنَٰكَ عَلَيۡهِمۡ حَفِيظٗاۖ وَمَآ أَنتَ عَلَيۡهِم بِوَكِيلٖ ﴿١٠٧﴾", "w": [["بصائر من ربكم", "جمع بصيرة، والمراد بها هنا الآيات المعرّفة بالحق المثبتة له بطريق الحجج العقلية، فهي في قوة العين المبصرة لصاحبها."], ["حفيظ", "وكيل مسؤول."], ["نصرّف الآيات", "نُجريها في مجارٍ مختلفة تبياناً للحق وتوضيحاً للهدى المطلوب."], ["وليقولوا درست", "أي تعلّمت وقرأت، لا وحياً أوحي إليك."], ["وأعرض عن المشركين", "لا تلتفت إليهم، وامضِ في طريق دعوتك."], ["ولو شاء الله ما أشركوا", "لو شاء أن يحول بينهم وبين الشرك حتى لا يشركوا لفعل."]], "m": "ما زال السياق في طلب هداية المشركين: قد جاءكم أيها الناس بصائر من ربكم، آيات القرآن الموضّحة لطريق النجاة، فمن أبصر بها فلنفسه، إذ هو الذي ينجو ويسعد، ومن عمي فعليها، إذ هي التي تهلك وتشقى، وقل لهم: ما أنا عليكم بوكيل مسؤول عن هدايتكم. وكذلك نصرّف الآيات لهداية مريدي الهداية، أما غيرهم فسيقولون: درست وتعلّمت من غيرك، فيُحرمون الإيمان، ولنبيّنه لقوم يعلمون. ثم أمر رسوله باتباع ما يوحى إليه، لا إله إلا هو، والإعراض عن المشركين المعاندين. وسلّاه وخفّف عنه آلام إعراضهم: ولو شاء الله ما أشركوا، فلا تحزن عليهم، وما جعلناك عليهم حفيظاً تحصي أعمالهم وتجازيهم بها، وما أنت عليهم بوكيل تتولّى هدايتهم بما فوق طاقتك، إن عليك إلا البلاغ، وقد بلّغت.", "h": ["آيات القرآن بصائر، من أخذ بها أبصر طريق الرشاد ونجا وسعد.", "ينتفع بتصريف الآيات وما تحمله من هدايات العالِمون لا الجاهلون، لقوله تعالى: «ولنبيّنه لقوم يعلمون».", "بيان الحكمة في تصريف الآيات، وهي هداية من شاء الله هدايته.", "وجوب اتباع الوحي المتمثّل في الكتاب والسنة النبوية.", "بيان بطلان مذهب القدرية نفاة القدر."], "k": "«فمن أبصر فلنفسه»… القرآن بين يديّ بصائر؛ فهل أفتحه لأرى به طريقي؟"}, {"lbl": "الآيات ١٠٨ – ١١٠", "q": "وَلَا تَسُبُّواْ ٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّواْ ٱللَّهَ عَدۡوَۢا بِغَيۡرِ عِلۡمٖۗ كَذَٰلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمۡ ثُمَّ إِلَىٰ رَبِّهِم مَّرۡجِعُهُمۡ فَيُنَبِّئُهُم بِمَا كَانُواْ يَعۡمَلُونَ ﴿١٠٨﴾ وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَئِن جَآءَتۡهُمۡ ءَايَةٞ لَّيُؤۡمِنُنَّ بِهَاۚ قُلۡ إِنَّمَا ٱلۡأٓيَٰتُ عِندَ ٱللَّهِۖ وَمَا يُشۡعِرُكُمۡ أَنَّهَآ إِذَا جَآءَتۡ لَا يُؤۡمِنُونَ ﴿١٠٩﴾ وَنُقَلِّبُ أَفۡـِٔدَتَهُمۡ وَأَبۡصَٰرَهُمۡ كَمَا لَمۡ يُؤۡمِنُواْ بِهِۦٓ أَوَّلَ مَرَّةٖ وَنَذَرُهُمۡ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ ﴿١١٠﴾", "w": [["ولا تسبّوا", "ولا تشتموا آلهة المشركين، حتى لا يسبّوا الله تعالى."], ["عدواً", "ظلماً."], ["زيّنا لكل أمة عملهم", "حسّناه لهم، خيراً كان أو شراً، حتى فعلوه."], ["جهد أيمانهم", "غاية اجتهادهم في حلفهم بالله."], ["آية", "معجزة كإحياء الموتى ونحوها."], ["وما يشعركم", "وما يُدريكم."], ["ونذرهم", "نتركهم."], ["يعمهون", "حيارى يتردّدون."]], "m": "لما أصبح رسول الله ﷺ يصدع بالدعوة جهراً، أخذ بعض أصحابه يسبّون أوثان المشركين، فغضب المشركون وأخذوا يسبّون الله رب المؤمنين، فنهاهم الله: ولا تسبّوا الذين يدعون من دون الله فيسبّوا الله ظلماً واعتداءً بغير علم، إذ لو علموا جلال الله وكماله لما سبّوه. كذلك زيّنا لكل أمة عملهم، وهي سنته في خلقه: أن المرء إذا أحب شيئاً وواصل ذلك الحب أصبح زيناً له ولو كان في الواقع شيناً، ومن هذا الباب كان دفاع المشركين عن آلهتهم الباطلة، ثم إلى ربهم مرجعهم فينبّئهم بما كانوا يعملون ويجزيهم: الخير بالخير والشر بالشر. وأقسم رؤساء المشركين بالله أبلغ أيمانهم: لئن جاءتهم آية كتحويل جبل الصفا ذهباً ليؤمننّ بها، والله يعلم أنهم لا يؤمنون، فأمر رسوله أن يقول: إنما الآيات عند الله يأتي بها إن شاء. ورغب بعض المؤمنين في مجيء الآية حتى يؤمن المشركون وينتهي الصراع، فقال لهم: وما يُدريكم أنها إذا جاءت لا يؤمنون؟ ونقلّب أفئدتهم فلا تعي، وأبصارهم فلا تبصر، كما لم يؤمنوا بالقرآن أول مرة، ونذرهم في طغيانهم حيارى يتردّدون، لا يعرفون الحق من الباطل.", "h": ["حرمة قول أو فعل ما يتسبّب عنه سب الله ورسوله.", "بيان سنة الله في تزيين الأعمال لأصحابها، خيراً كانت أو شراً.", "بيان أن الهداية بيد الله تعالى، وأن المعجزات قد لا يؤمن عليها من شاهدها."], "k": "«ولا تسبّوا الذين يدعون من دون الله»… هل يجرّ كلامي أو غضبي غيري إلى الإساءة إلى ديني؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 94;
insert into public.tdb_cards(topic, i, body) select 94, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٠٠ – ١٠٣", "q": "وَجَعَلُواْ لِلَّهِ شُرَكَآءَ ٱلۡجِنَّ وَخَلَقَهُمۡۖ وَخَرَقُواْ لَهُۥ بَنِينَ وَبَنَٰتِۭ بِغَيۡرِ عِلۡمٖۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَصِفُونَ ﴿١٠٠﴾ بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ أَنَّىٰ يَكُونُ لَهُۥ وَلَدٞ وَلَمۡ تَكُن لَّهُۥ صَٰحِبَةٞۖ وَخَلَقَ كُلَّ شَيۡءٖۖ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٞ ﴿١٠١﴾ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡۖ لَآ إِلَٰهَ إِلَّا هُوَۖ خَٰلِقُ كُلِّ شَيۡءٖ فَٱعۡبُدُوهُۚ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ وَكِيلٞ ﴿١٠٢﴾ لَّا تُدۡرِكُهُ ٱلۡأَبۡصَٰرُ وَهُوَ يُدۡرِكُ ٱلۡأَبۡصَٰرَۖ وَهُوَ ٱللَّطِيفُ ٱلۡخَبِيرُ ﴿١٠٣﴾", "w": [["شركاء", "جمع شريك في عبادته تعالى."], ["الجن", "عالم كعالم الإنس، إلا أنهم أجسام خفية لا تُرى لنا إلا إذا تشكّلت بما يُرى."], ["وخرقوا", "اختلقوا وافتاتوا."], ["يصفون", "من صفات العجز، بنسبة الولد والشريك إليه."], ["بديع السماوات والأرض", "مبدع خلقهما، حيث أوجدهما على غير مثال سابق."], ["أنى يكون له ولد", "كيف يكون له ولد كما يقول المبطلون؟"], ["ولم تكن له صاحبة", "أي زوجة."], ["لا تدركه الأبصار", "لا تراه في الدنيا، ولا تحيط به في الآخرة."], ["وهو يدرك الأبصار", "محيط علمه بها."], ["وهو اللطيف", "الذي ينفذ علمه إلى بواطن الأمور وخفايا الأسرار فلا يحجبه شيء."]], "m": "مع ما سبق من البراهين الباهرة على التوحيد، جعل الجاهلون لله شركاء الجن، فأطاعوهم فيما زيّنوا لهم من عبادة الأصنام، والحال أنه خلقهم، فالكل مخلوق له: العابد والمعبود. وزادوا في ضلالهم فاختلقوا له بنين وبنات بغير علم، لا دليل عقلي ولا نقلي، كما قال مشركو العرب: الملائكة بنات الله، واليهود: عزير ابن الله، والنصارى: المسيح ابن الله، سبحانه وتعالى عما يصفون. ثم أقام الدليل على بطلان هذه الفرية: بديع السماوات والأرض، خالقهما على غير مثال سابق، كيف يكون له ولد ولم تكن له زوجة؟ والتوالد إنما يكون بين ذكر وأنثى لحاجة حفظ النوع وعمارة الأرض، وهو خالق كل شيء ورب كل شيء، وهو بكل شيء عليم، فلو كان له ولد لعلمه. ذلكم الله ربكم لا إله إلا هو خالق كل شيء فاعبدوه، وهو على كل شيء وكيل، كفيل برزقكم وحفظكم ومجازاتكم. وهو مباين خلقه في ذاته وصفاته، لا تدركه الأبصار وهو يدركها، وهو اللطيف الذي ينفذ علمه وقدرته في كل ذرات الكون، الخبير بكل خلقه.", "h": ["من الإنس من عبد الجن، بطاعتهم وقبول ما يأمرونهم به ويزيّنونه لهم.", "تنزّه الرب تعالى عن الشريك والصاحبة والولد.", "مباينة الرب تبارك وتعالى لخلقه.", "استحالة رؤية الرب في الدنيا، وجوازها في الآخرة لأوليائه في دار كرامته."], "k": "«وهو اللطيف الخبير»… ربي يعلم خفايا نفسي التي لا يراها أحد؛ فهل أُصلحها كما أُصلح ظاهري؟"}, {"lbl": "الآيات ١٠٤ – ١٠٧", "q": "قَدۡ جَآءَكُم بَصَآئِرُ مِن رَّبِّكُمۡۖ فَمَنۡ أَبۡصَرَ فَلِنَفۡسِهِۦۖ وَمَنۡ عَمِيَ فَعَلَيۡهَاۚ وَمَآ أَنَا۠ عَلَيۡكُم بِحَفِيظٖ ﴿١٠٤﴾ وَكَذَٰلِكَ نُصَرِّفُ ٱلۡأٓيَٰتِ وَلِيَقُولُواْ دَرَسۡتَ وَلِنُبَيِّنَهُۥ لِقَوۡمٖ يَعۡلَمُونَ ﴿١٠٥﴾ ٱتَّبِعۡ مَآ أُوحِيَ إِلَيۡكَ مِن رَّبِّكَۖ لَآ إِلَٰهَ إِلَّا هُوَۖ وَأَعۡرِضۡ عَنِ ٱلۡمُشۡرِكِينَ ﴿١٠٦﴾ وَلَوۡ شَآءَ ٱللَّهُ مَآ أَشۡرَكُواْۗ وَمَا جَعَلۡنَٰكَ عَلَيۡهِمۡ حَفِيظٗاۖ وَمَآ أَنتَ عَلَيۡهِم بِوَكِيلٖ ﴿١٠٧﴾", "w": [["بصائر من ربكم", "جمع بصيرة، والمراد بها هنا الآيات المعرّفة بالحق المثبتة له بطريق الحجج العقلية، فهي في قوة العين المبصرة لصاحبها."], ["حفيظ", "وكيل مسؤول."], ["نصرّف الآيات", "نُجريها في مجارٍ مختلفة تبياناً للحق وتوضيحاً للهدى المطلوب."], ["وليقولوا درست", "أي تعلّمت وقرأت، لا وحياً أوحي إليك."], ["وأعرض عن المشركين", "لا تلتفت إليهم، وامضِ في طريق دعوتك."], ["ولو شاء الله ما أشركوا", "لو شاء أن يحول بينهم وبين الشرك حتى لا يشركوا لفعل."]], "m": "ما زال السياق في طلب هداية المشركين: قد جاءكم أيها الناس بصائر من ربكم، آيات القرآن الموضّحة لطريق النجاة، فمن أبصر بها فلنفسه، إذ هو الذي ينجو ويسعد، ومن عمي فعليها، إذ هي التي تهلك وتشقى، وقل لهم: ما أنا عليكم بوكيل مسؤول عن هدايتكم. وكذلك نصرّف الآيات لهداية مريدي الهداية، أما غيرهم فسيقولون: درست وتعلّمت من غيرك، فيُحرمون الإيمان، ولنبيّنه لقوم يعلمون. ثم أمر رسوله باتباع ما يوحى إليه، لا إله إلا هو، والإعراض عن المشركين المعاندين. وسلّاه وخفّف عنه آلام إعراضهم: ولو شاء الله ما أشركوا، فلا تحزن عليهم، وما جعلناك عليهم حفيظاً تحصي أعمالهم وتجازيهم بها، وما أنت عليهم بوكيل تتولّى هدايتهم بما فوق طاقتك، إن عليك إلا البلاغ، وقد بلّغت.", "h": ["آيات القرآن بصائر، من أخذ بها أبصر طريق الرشاد ونجا وسعد.", "ينتفع بتصريف الآيات وما تحمله من هدايات العالِمون لا الجاهلون، لقوله تعالى: «ولنبيّنه لقوم يعلمون».", "بيان الحكمة في تصريف الآيات، وهي هداية من شاء الله هدايته.", "وجوب اتباع الوحي المتمثّل في الكتاب والسنة النبوية.", "بيان بطلان مذهب القدرية نفاة القدر."], "k": "«فمن أبصر فلنفسه»… القرآن بين يديّ بصائر؛ فهل أفتحه لأرى به طريقي؟"}, {"lbl": "الآيات ١٠٨ – ١١٠", "q": "وَلَا تَسُبُّواْ ٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّواْ ٱللَّهَ عَدۡوَۢا بِغَيۡرِ عِلۡمٖۗ كَذَٰلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمۡ ثُمَّ إِلَىٰ رَبِّهِم مَّرۡجِعُهُمۡ فَيُنَبِّئُهُم بِمَا كَانُواْ يَعۡمَلُونَ ﴿١٠٨﴾ وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَئِن جَآءَتۡهُمۡ ءَايَةٞ لَّيُؤۡمِنُنَّ بِهَاۚ قُلۡ إِنَّمَا ٱلۡأٓيَٰتُ عِندَ ٱللَّهِۖ وَمَا يُشۡعِرُكُمۡ أَنَّهَآ إِذَا جَآءَتۡ لَا يُؤۡمِنُونَ ﴿١٠٩﴾ وَنُقَلِّبُ أَفۡـِٔدَتَهُمۡ وَأَبۡصَٰرَهُمۡ كَمَا لَمۡ يُؤۡمِنُواْ بِهِۦٓ أَوَّلَ مَرَّةٖ وَنَذَرُهُمۡ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ ﴿١١٠﴾", "w": [["ولا تسبّوا", "ولا تشتموا آلهة المشركين، حتى لا يسبّوا الله تعالى."], ["عدواً", "ظلماً."], ["زيّنا لكل أمة عملهم", "حسّناه لهم، خيراً كان أو شراً، حتى فعلوه."], ["جهد أيمانهم", "غاية اجتهادهم في حلفهم بالله."], ["آية", "معجزة كإحياء الموتى ونحوها."], ["وما يشعركم", "وما يُدريكم."], ["ونذرهم", "نتركهم."], ["يعمهون", "حيارى يتردّدون."]], "m": "لما أصبح رسول الله ﷺ يصدع بالدعوة جهراً، أخذ بعض أصحابه يسبّون أوثان المشركين، فغضب المشركون وأخذوا يسبّون الله رب المؤمنين، فنهاهم الله: ولا تسبّوا الذين يدعون من دون الله فيسبّوا الله ظلماً واعتداءً بغير علم، إذ لو علموا جلال الله وكماله لما سبّوه. كذلك زيّنا لكل أمة عملهم، وهي سنته في خلقه: أن المرء إذا أحب شيئاً وواصل ذلك الحب أصبح زيناً له ولو كان في الواقع شيناً، ومن هذا الباب كان دفاع المشركين عن آلهتهم الباطلة، ثم إلى ربهم مرجعهم فينبّئهم بما كانوا يعملون ويجزيهم: الخير بالخير والشر بالشر. وأقسم رؤساء المشركين بالله أبلغ أيمانهم: لئن جاءتهم آية كتحويل جبل الصفا ذهباً ليؤمننّ بها، والله يعلم أنهم لا يؤمنون، فأمر رسوله أن يقول: إنما الآيات عند الله يأتي بها إن شاء. ورغب بعض المؤمنين في مجيء الآية حتى يؤمن المشركون وينتهي الصراع، فقال لهم: وما يُدريكم أنها إذا جاءت لا يؤمنون؟ ونقلّب أفئدتهم فلا تعي، وأبصارهم فلا تبصر، كما لم يؤمنوا بالقرآن أول مرة، ونذرهم في طغيانهم حيارى يتردّدون، لا يعرفون الحق من الباطل.", "h": ["حرمة قول أو فعل ما يتسبّب عنه سب الله ورسوله.", "بيان سنة الله في تزيين الأعمال لأصحابها، خيراً كانت أو شراً.", "بيان أن الهداية بيد الله تعالى، وأن المعجزات قد لا يؤمن عليها من شاهدها."], "k": "«ولا تسبّوا الذين يدعون من دون الله»… هل يجرّ كلامي أو غضبي غيري إلى الإساءة إلى ديني؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;